export function PElement({
  text = "{{text}}",
  size = "{{size}}",
  accent = "{{accent}}",
  measure = {{measure}},
}) {
  const sizes = {
    lead: { fontSize: 19, lineHeight: 1.5, fontWeight: 500 },
    body: { fontSize: 15, lineHeight: 1.65 },
    small: { fontSize: 13, lineHeight: 1.55, opacity: 0.75 },
  };
  return (
    <div style={{ width: 380, boxSizing: "border-box", fontFamily: "system-ui, sans-serif", background: "#FAF7F2", padding: 20, borderRadius: 12 }}>
      <p style={{ margin: 0, color: accent, maxWidth: measure ? "34ch" : "none", ...(sizes[size] ?? sizes.body) }}>{text}</p>
    </div>
  );
}
